using UnityEngine;
namespace Blocklands {
 public class PalaceLife:MonoBehaviour {
  Sandbox game;RoyalArt art;Transform carousel,thief,escort,swing;Transform[] children;LineRenderer[] ropes;Material ropeMaterial;Vector3 entry;float rideAge,thiefAge;int ride;bool rewarded,bodyWasEnabled;CastleBallPlay ballGame;
  public bool Locked=>ride!=0;public bool ConsoleOpen {get;private set;}public bool PatrolActive {get;private set;}public bool ThiefCaught {get;private set;}public Vector3 SafeExit=>entry;public Vector3 ThiefPosition=>thief!=null?thief.position:Vector3.zero;
  public static readonly Vector3 CarouselPoint=new Vector3(39,16,7),SwingPoint=new Vector3(20,16,7),SlidePoint=new Vector3(46,16,9),BankPoint=new Vector3(39,16,38),PatrolPoint=new Vector3(31,16,20);
  Font font;
  public void Initialize(Sandbox g){game=g;font=Resources.Load<Font>("NotoSansCJKsc-Regular");art=gameObject.AddComponent<RoyalArt>();BuildPlayground();foreach(var child in GetComponentsInChildren<CastleGirlStyle>())child.gameObject.AddComponent<NeighbourSpeech>().Initialize(game,NeighbourSpeechKind.CastleEnvy);var disc=transform.Find("旋转木马基座");if(disc!=null)CastleBallPlay.UseFlatDiscCollider(disc);BuildVault();BuildPatrol();var court=new GameObject("城堡伙伴传球区");court.transform.SetParent(transform,false);ballGame=court.AddComponent<CastleBallPlay>();ballGame.Initialize(g);}
  Transform Piece(string name,Vector3 p,Vector3 size,Color color,bool solid=false){return art.Piece(name,p,size,color,PrimitiveType.Cube,solid);}
  void Sign(Vector3 p,string text){Piece("互动指示牌",p,new Vector3(2.5f,.65f,.12f),new Color(.25f,.32f,.42f));var o=new GameObject("指示文字").transform;o.SetParent(transform,false);o.localPosition=p+Vector3.back*.075f;var t=o.gameObject.AddComponent<TextMesh>();t.font=font;o.GetComponent<Renderer>().sharedMaterial=font.material;t.text=text;t.characterSize=.08f;t.fontSize=36;t.anchor=TextAnchor.MiddleCenter;t.color=Color.white;}
  void BuildPlayground(){Color pink=new Color(.96f,.53f,.75f),gold=new Color(1,.78f,.35f),mint=new Color(.4f,.8f,.72f);var baseDisc=art.Piece("旋转木马基座",CarouselPoint-Vector3.up*.16f,new Vector3(6,.16f,6),pink,PrimitiveType.Cylinder,true);carousel=new GameObject("旋转木马转盘").transform;carousel.SetParent(transform,false);carousel.position=CarouselPoint;var a=carousel.gameObject.AddComponent<RoyalArt>();a.Piece("中央金柱",Vector3.up*1.8f,new Vector3(.3f,3.6f,.3f),gold);a.Taper("糖果旋转木马顶棚",Vector3.up*3.6f,new Vector3(6,.6f,6),pink,.08f);children=new Transform[4];for(int i=0;i<4;i++){float angle=i*Mathf.PI/2;var seat=new GameObject("木马座位 "+i).transform;seat.SetParent(carousel,false);seat.localPosition=new Vector3(Mathf.Sin(angle)*2,0,Mathf.Cos(angle)*2);seat.localRotation=Quaternion.Euler(0,i*90,0);var horse=seat.gameObject.AddComponent<RoyalArt>();horse.Piece("木马身体",Vector3.up*.85f,new Vector3(.7f,.6f,1.25f),i%2==0?mint:Color.white);horse.Piece("马头",new Vector3(0,1.25f,.62f),new Vector3(.45f,.6f,.45f),i%2==0?mint:Color.white);horse.Piece("鞍垫",new Vector3(0,1.2f,0),new Vector3(.72f,.12f,.65f),gold);horse.Piece("扶杆",new Vector3(0,1.9f,0),new Vector3(.06f,3.7f,.06f),gold);if(i>0){var kid=CastleGirlStyle.Make(seat,i);kid.transform.localPosition=new Vector3(0,1.05f,-.15f);children[i]=kid.transform;}}
   Sign(CarouselPoint+new Vector3(0,1.1f,-3.1f),"旋转木马 · G上下车");foreach(float side in new[]{-1.4f,1.4f})Piece("秋千支架",SwingPoint+new Vector3(side,1.5f,0),new Vector3(.18f,3,.18f),mint);Piece("秋千横杆",SwingPoint+Vector3.up*3,new Vector3(3,.18f,.18f),gold);swing=Piece("秋千软座",SwingPoint+Vector3.up*.65f,new Vector3(1.25f,.16f,.6f),pink);ropeMaterial=new Material(Resources.Load<Shader>("Selection"));ropeMaterial.color=gold;ropes=new LineRenderer[2];for(int i=0;i<2;i++){var o=new GameObject("秋千绳");o.transform.SetParent(transform,false);var l=o.AddComponent<LineRenderer>();l.sharedMaterial=ropeMaterial;l.widthMultiplier=.045f;l.positionCount=2;ropes[i]=l;}
   Sign(SwingPoint+new Vector3(0,1,-2),"秋千 · G坐下/起身");var slope=Piece("糖果滑梯",SlidePoint+new Vector3(0,1.2f,-1.2f),new Vector3(1.6f,.2f,4),mint);slope.rotation=Quaternion.Euler(-35,0,0);for(int i=0;i<5;i++)Piece("滑梯台阶",SlidePoint+new Vector3(0,i*.4f,i*.35f),new Vector3(1.8f,.25f,.45f),pink);Sign(SlidePoint+new Vector3(1.3f,1,-2),"大滑梯 · G滑下来");
   var friend=CastleGirlStyle.Make(transform,0);friend.transform.position=SwingPoint+new Vector3(2,-1,1);children[0]=friend.transform;Piece("游乐区长椅",new Vector3(25,16.4f,6),new Vector3(3,.3f,.9f),pink);Piece("长椅靠背",new Vector3(25,17,6.4f),new Vector3(3,1,.15f),mint);}
  void BuildVault(){Color gold=new Color(.92f,.7f,.25f),steel=new Color(.25f,.31f,.4f);Piece("皇家金库后墙",new Vector3(41,18,44),new Vector3(7,4,.3f),steel);foreach(float x in new[]{37.5f,44.5f})Piece("金库侧墙",new Vector3(x,18,41),new Vector3(.25f,4,6),steel);Piece("金库门框",new Vector3(41,19.8f,37.8f),new Vector3(7,.35f,.5f),gold);for(int i=0;i<12;i++)Piece("金库金锭",new Vector3(39.5f+(i%3)*1.1f,16.45f+(i/3)*.35f,42),new Vector3(.9f,.27f,.6f),gold);Piece("银行柜台",BankPoint+new Vector3(0,.5f,0),new Vector3(2,1,.8f),new Color(.55f,.3f,.2f));Piece("金库电脑",BankPoint+new Vector3(0,1.45f,0),new Vector3(1.3f,.8f,.12f),steel);Piece("电脑屏幕",BankPoint+new Vector3(0,1.45f,-.07f),new Vector3(1.15f,.65f,.02f),new Color(.22f,.78f,.68f));Piece("电脑键盘",BankPoint+new Vector3(0,1.04f,-.3f),new Vector3(1.2f,.05f,.25f),steel);Sign(BankPoint+new Vector3(0,2.3f,0),"皇家金库 · G电脑");}
  void BuildPatrol(){Sign(PatrolPoint+new Vector3(-3,1.5f,0),"皇家巡逻 · G接任务");thief=RoyalArt.Girl(transform,false,false).transform;thief.name="可疑的钱袋访客";thief.position=PatrolPoint+Vector3.forward*8;var a=thief.GetComponent<RoyalArt>();a.Piece("黑色眼罩",new Vector3(0,1.6f,.23f),new Vector3(.43f,.13f,.04f),Color.black);a.Piece("偷走的钱袋",new Vector3(.38f,.7f,.12f),new Vector3(.4f,.5f,.35f),new Color(.85f,.59f,.18f),PrimitiveType.Sphere);thief.gameObject.SetActive(false);}
  public bool Interact(){if(game.Paused)return false;if(ConsoleOpen){CloseConsole();return true;}if(Locked){StopRide();return true;}Vector3 p=game.Player.transform.position;
   if(ballGame!=null&&ballGame.NearPlayer){ballGame.PassFromPlayer();return true;}
   if(PatrolActive&&Vector3.Distance(p,thief.position)<2.8f){CatchThief();return true;}if(Vector3.Distance(p,BankPoint)<3.4f){if(!game.RoyalIdentity){game.Notice="金库电脑只接受公主的皇冠身份。";return true;}ConsoleOpen=true;game.Notice="皇家金库电脑：存钱与取钱。";return true;}
   if(Vector3.Distance(p,CarouselPoint)<4){StartRide(1);return true;}if(Vector3.Distance(p,SwingPoint)<3){StartRide(2);return true;}if(Vector3.Distance(p,SlidePoint)<3.5f){StartRide(3);return true;}if(Vector3.Distance(p,PatrolPoint)<4){StartPatrol();return true;}return false;}
  public void StartRide(int type){if(Locked||game.HomeSeated||game.HoldingBook||game.RoyalThroneSeated||game.RoyalTransportActive||game.FestivalLocked)return;ride=type;rideAge=0;entry=game.Player.transform.position;bodyWasEnabled=game.Player.Body.enabled;game.Player.SetFlying(false);game.Player.Body.enabled=false;game.Player.HomeRest(true);game.Notice="正在游玩，G随时起身。";}
  public void StopRide(){if(!Locked)return;int award=ride==1&&rideAge>=20?28:ride==2&&rideAge>=6?18:ride==3&&rideAge>=3?22:0;ride=0;game.Player.Body.enabled=bodyWasEnabled;game.Player.HomeRest(false);game.Player.Teleport(entry,game.Player.transform.eulerAngles.y,game.Player.Pitch);if(award>0)game.EarnActivityCoins(award,"皇宫游乐设施");else game.Notice="已安全起身。木马转一圈、秋千玩满6秒或滑到底可领取金币。";}
  public bool StartPatrol(){if(!game.RoyalIdentity){game.Notice="成为公主后，可以接皇家巡逻任务。";return false;}if(PatrolActive)return false;PatrolActive=true;ThiefCaught=false;thiefAge=0;thief.position=PatrolPoint+Vector3.forward*8;thief.gameObject.SetActive(true);game.Notice="找到抱着金色钱袋的可疑访客，靠近按G请卫兵接管。";return true;}
  public bool CatchThief(){if(!PatrolActive||Vector3.Distance(game.Player.transform.position,thief.position)>2.8f)return false;PatrolActive=false;ThiefCaught=true;thiefAge=0;if(escort!=null)Destroy(escort.gameObject);escort=RoyalArt.Girl(transform,false,false).transform;escort.name="押送卫兵";escort.position=thief.position+Vector3.right;int earned=game.EarnActivityCoins(50,"皇家巡逻");if(earned>0)game.Notice="卫兵接管小偷，钱袋追回。这次获得"+earned+"元。";return true;}
  public void CloseConsole(){ConsoleOpen=false;}
  void Update(){if(game==null||game.Paused)return;float t=Time.time;carousel.localRotation=Quaternion.Euler(0,t*18,0);swing.position=SwingPoint+new Vector3(0,.65f+(1-Mathf.Cos(Mathf.Sin(t)*.5f))*2,Mathf.Sin(t)*.9f);for(int i=0;i<2;i++){float x=i==0?-.55f:.55f;ropes[i].SetPosition(0,SwingPoint+new Vector3(x,3,0));ropes[i].SetPosition(1,swing.position+new Vector3(x,0,0));}
   if(Locked){rideAge+=Time.deltaTime;Vector3 p=ride==1?carousel.TransformPoint(new Vector3(0,1.25f,2)):ride==2?swing.position+Vector3.up*.25f:Vector3.Lerp(SlidePoint+new Vector3(0,2.4f,1),SlidePoint+new Vector3(0,.2f,-3),Mathf.SmoothStep(0,1,Mathf.Clamp01(rideAge/3)));game.Player.MoveCoasterSeat(p);if(ride==3&&rideAge>=3)StopRide();}
   if(PatrolActive){thiefAge+=Time.deltaTime;Vector3 goal=new Vector3(31+Mathf.Sin(thiefAge*.24f)*10,16,31+Mathf.Cos(thiefAge*.24f)*9);Vector3 d=goal-thief.position;thief.position=Vector3.MoveTowards(thief.position,goal,Time.deltaTime*2.6f);if(d.sqrMagnitude>.01f)thief.rotation=Quaternion.LookRotation(d);if(thiefAge>90){PatrolActive=false;thief.gameObject.SetActive(false);game.Notice="小偷离开了，可以回任务牌再接一次巡逻。";}}else if(ThiefCaught&&thief.gameObject.activeSelf){thiefAge+=Time.deltaTime;thief.position=Vector3.MoveTowards(thief.position,new Vector3(31,16,15),Time.deltaTime*3);if(escort!=null)escort.position=thief.position+Vector3.right;if(thiefAge>6){thief.gameObject.SetActive(false);if(escort!=null)escort.gameObject.SetActive(false);}}
  }
  public void Draw(float w,float h){if(game.Paused)return;var style=new GUIStyle(GUI.skin.label){font=font,fontSize=17,wordWrap=true};style.normal.textColor=Color.white;if(ConsoleOpen){float x=w/2-230,y=h/2-170;GUI.Box(new Rect(x,y,460,340),"");GUI.Label(new Rect(x+24,y+20,412,70),"皇家金库电脑\n钱包："+game.Inventory[(int)Block.Coin]+"  金库："+game.PalaceSavings,style);if(GUI.Button(new Rect(x+28,y+106,192,48),"存入100元"))game.TransferPalaceMoney(100);if(GUI.Button(new Rect(x+240,y+106,192,48),"取出100元"))game.TransferPalaceMoney(-100);GUI.Label(new Rect(x+24,y+170,412,90),game.Notice,style);if(GUI.Button(new Rect(x+100,y+275,260,38),"关闭 · Esc / G"))CloseConsole();return;}if(Locked)GUI.Label(new Rect(20,210,650,40),"皇宫游乐区 · 鼠标环顾 · G起身",style);else if(PatrolActive)GUI.Label(new Rect(20,210,650,65),"皇家巡逻：靠近金色钱袋访客按G\n距离："+Mathf.RoundToInt(Vector3.Distance(game.Player.transform.position,thief.position))+"米",style);}
  void OnDestroy(){if(Locked&&game!=null&&game.Player!=null){game.Player.Body.enabled=bodyWasEnabled;game.Player.HomeRest(false);}if(ropeMaterial!=null)Destroy(ropeMaterial);}
 }
 public partial class Sandbox {
  public PalaceLife PalaceLeisure {get;private set;}public bool PalacePlayLocked=>PalaceLeisure!=null&&PalaceLeisure.Locked;public bool PalaceConsoleOpen=>PalaceLeisure!=null&&PalaceLeisure.ConsoleOpen;public int PalaceSavings {get;private set;}
  void BuildPalaceLeisure(){PalaceLeisure=null;if(World.Region!=6)return;var root=new GameObject("皇宫生活游乐区");root.transform.SetParent(villagePeople.transform);PalaceLeisure=root.AddComponent<PalaceLife>();PalaceLeisure.Initialize(this);}
  public bool TransferPalaceMoney(int amount){if(saveBlocked){Notice="存档尚未恢复，金库暂不可用，金额保持不变。";return false;}if(!RoyalIdentity||Mathf.Abs(amount)!=100||amount>0&&Inventory[(int)Block.Coin]<amount||amount<0&&(PalaceSavings<100||Inventory[(int)Block.Coin]>9899)||amount>0&&PalaceSavings>999900){Notice="余额不足，或钱包/金库已满。";return false;}int before=PalaceSavings,wallet=Inventory[(int)Block.Coin];PalaceSavings+=amount;Inventory[(int)Block.Coin]-=amount;try{WorldSave.Write(WorldSave.Capture(World,Player,Inventory,Selected),WorldSave.PathName);Notice=amount>0?"已存入100元，下次回来仍保留。":"已取出100元。";return true;}catch(System.Exception){PalaceSavings=before;Inventory[(int)Block.Coin]=wallet;Notice="保存未成功，金额没有改变。";return false;}}
 }
}
